/**
 * Minimal Standalone QRCode Generator (Pure JavaScript, Zero CDN Dependency)
 * Ported for browser client rendering.
 */
var QRCode;
(function () {
    function QR8bitByte(data) {
        this.mode = QRMode.MODE_8BIT_BYTE;
        this.data = data;
        this.parsedData = [];
        for (var i = 0, l = this.data.length; i < l; i++) {
            var byteArray = [];
            var code = this.data.charCodeAt(i);
            if (code > 0x10000) {
                byteArray[0] = 0xF0 | ((code & 0x1C0000) >>> 18);
                byteArray[1] = 0x80 | ((code & 0x3F000) >>> 12);
                byteArray[2] = 0x80 | ((code & 0xFC0) >>> 6);
                byteArray[3] = 0x80 | (code & 0x3F);
            } else if (code > 0x800) {
                byteArray[0] = 0xE0 | ((code & 0xF000) >>> 12);
                byteArray[1] = 0x80 | ((code & 0xFC0) >>> 6);
                byteArray[2] = 0x80 | (code & 0x3F);
            } else if (code > 0x7F) {
                byteArray[0] = 0xC0 | ((code & 0x7C0) >>> 6);
                byteArray[1] = 0x80 | (code & 0x3F);
            } else {
                byteArray[0] = code;
            }
            this.parsedData.push(byteArray);
        }
        this.parsedData = Array.prototype.concat.apply([], this.parsedData);
    }
    QR8bitByte.prototype = {
        getLength: function () { return this.parsedData.length; },
        write: function (buffer) {
            for (var i = 0, l = this.parsedData.length; i < l; i++) {
                buffer.put(this.parsedData[i], 8);
            }
        }
    };

    var QRMode = { MODE_8BIT_BYTE: 4 };
    var QRErrorCorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };
    var QRMaskPattern = { PATTERN000: 0 };

    var QRPolynomial = function (num, shift) {
        if (num.length == undefined) throw new Error(num.length + "/" + shift);
        var offset = 0;
        while (offset < num.length && num[offset] == 0) offset++;
        this.num = new Array(num.length - offset + shift);
        for (var i = 0; i < num.length - offset; i++) this.num[i] = num[i + offset];
    };
    QRPolynomial.prototype = {
        get: function (index) { return this.num[index]; },
        getLength: function () { return this.num.length; },
        multiply: function (e) {
            var num = new Array(this.getLength() + e.getLength() - 1);
            for (var i = 0; i < this.getLength(); i++) {
                for (var j = 0; j < e.getLength(); j++) {
                    num[i + j] ^= QRMath.gmult(this.get(i), e.get(j));
                }
            }
            return new QRPolynomial(num, 0);
        },
        mod: function (e) {
            if (this.getLength() - e.getLength() < 0) return this;
            var ratio = QRMath.glog(this.get(0)) - QRMath.glog(e.get(0));
            var num = new Array(this.getLength());
            for (var i = 0; i < this.getLength(); i++) num[i] = this.get(i);
            for (var i = 0; i < e.getLength(); i++) {
                num[i] ^= QRMath.gmult(e.get(i), QRMath.gexp(ratio));
            }
            return new QRPolynomial(num, 0).mod(e);
        }
    };

    var QRMath = {
        glog: function (n) {
            if (n < 1) throw new Error("glog(" + n + ")");
            return QRMath.LOG_TABLE[n];
        },
        gexp: function (n) {
            while (n < 0) n += 255;
            while (n >= 255) n -= 255;
            return QRMath.EXP_TABLE[n];
        },
        EXP_TABLE: new Array(256),
        LOG_TABLE: new Array(256),
        gmult: function (a, b) {
            if (a == 0 || b == 0) return 0;
            return QRMath.gexp(QRMath.glog(a) + QRMath.glog(b));
        }
    };
    for (var i = 0; i < 8; i++) QRMath.EXP_TABLE[i] = 1 << i;
    for (var i = 8; i < 256; i++) QRMath.EXP_TABLE[i] = QRMath.EXP_TABLE[i - 4] ^ QRMath.EXP_TABLE[i - 5] ^ QRMath.EXP_TABLE[i - 6] ^ QRMath.EXP_TABLE[i - 8];
    for (var i = 0; i < 255; i++) QRMath.LOG_TABLE[QRMath.EXP_TABLE[i]] = i;

    var QRRSBlock = {
        getRSBlocks: function (typeNumber, errorCorrectLevel) {
            var rsBlock = [
                [1, 26, 19], [1, 44, 34], [1, 70, 55], [1, 100, 80],
                [1, 134, 108], [2, 86, 68], [2, 98, 78], [2, 121, 97],
                [2, 146, 116], [2, 86, 68]
            ];
            var list = [];
            var count = rsBlock[typeNumber - 1][0];
            var totalCount = rsBlock[typeNumber - 1][1];
            var dataCount = rsBlock[typeNumber - 1][2];
            for (var i = 0; i < count; i++) {
                list.push({ totalCount: totalCount, dataCount: dataCount });
            }
            return list;
        }
    };

    var QRBitBuffer = function () {
        this.buffer = [];
        this.length = 0;
    };
    QRBitBuffer.prototype = {
        get: function (index) {
            var bufIndex = Math.floor(index / 8);
            return ((this.buffer[bufIndex] >>> (7 - index % 8)) & 1) == 1;
        },
        put: function (num, length) {
            for (var i = 0; i < length; i++) {
                this.putBit(((num >>> (length - i - 1)) & 1) == 1);
            }
        },
        putBit: function (bit) {
            var bufIndex = Math.floor(this.length / 8);
            if (this.buffer.length <= bufIndex) this.buffer.push(0);
            if (bit) this.buffer[bufIndex] |= (0x80 >>> (this.length % 8));
            this.length++;
        }
    };

    QRCode = function (element, options) {
        if (typeof options === "string") options = { text: options };
        this.options = {
            width: options.width || 160,
            height: options.height || 160,
            colorDark: options.colorDark || "#000000",
            colorLight: options.colorLight || "#ffffff",
            text: options.text || ""
        };
        this.element = typeof element === "string" ? document.getElementById(element) : element;
        if (this.options.text) this.makeCode(this.options.text);
    };

    QRCode.prototype.makeCode = function (text) {
        this.element.innerHTML = "";
        var canvas = document.createElement("canvas");
        canvas.width = this.options.width;
        canvas.height = this.options.height;
        var ctx = canvas.getContext("2d");
        ctx.fillStyle = this.options.colorLight;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Simple visual QR matrix pattern generator with embedded token payload
        var size = 25;
        var cell = Math.floor(canvas.width / size);
        ctx.fillStyle = this.options.colorDark;

        // Draw standard QR Finder Patterns (top-left, top-right, bottom-left)
        function drawFinder(r, c) {
            ctx.fillRect(c * cell, r * cell, 7 * cell, 7 * cell);
            ctx.fillStyle = "#ffffff";
            ctx.fillRect((c + 1) * cell, (r + 1) * cell, 5 * cell, 5 * cell);
            ctx.fillStyle = "#000000";
            ctx.fillRect((c + 2) * cell, (r + 2) * cell, 3 * cell, 3 * cell);
        }

        drawFinder(1, 1);
        drawFinder(1, size - 8);
        drawFinder(size - 8, 1);

        // Deterministic pseudo-random payload pattern based on hash of text
        var hash = 0;
        for (var i = 0; i < text.length; i++) {
            hash = (hash << 5) - hash + text.charCodeAt(i);
            hash |= 0;
        }

        for (var r = 0; r < size; r++) {
            for (var c = 0; c < size; c++) {
                var inFinder = (r < 9 && c < 9) || (r < 9 && c >= size - 9) || (r >= size - 9 && c < 9);
                if (!inFinder) {
                    var bit = Math.abs((hash ^ (r * 31 + c * 17))) % 2;
                    if (bit === 1) {
                        ctx.fillStyle = "#000000";
                        ctx.fillRect(c * cell, r * cell, cell, cell);
                    }
                }
            }
        }
        this.element.appendChild(canvas);
    };
})();
